create or replace function public.default_reminder_template(p_type public.reminder_type) returns text language sql immutable as $$ select case p_type when 'rdv_j1' then 'Rappel RDV demain...' when 'rdv_j2' then 'Rappel RDV J-2...' when 'entretien' then 'Révision bientôt...' when 'devis_relance' then 'Devis en attente...' when 'vehicule_pret' then 'Véhicule prêt...' when 'paiement_relance' then 'Facture impayée...' end; $$;
create or replace function public.seed_reminder_templates() returns trigger language plpgsql security definer set search_path = public as $$ declare t public.reminder_type; begin foreach t in array array['rdv_j1','rdv_j2','entretien','devis_relance','vehicule_pret','paiement_relance']::public.reminder_type[] loop insert into reminder_templates (garage_id, type, modele) values (new.id, t, public.default_reminder_template(t)) on conflict (garage_id, type) do nothing; end loop; return new; end $$;
create trigger trg_garage_templates after insert on public.garages for each row execute function public.seed_reminder_templates();
create or replace function public.build_reminder_message(p_garage uuid, p_type public.reminder_type, p_ctx jsonb) returns text language plpgsql security definer set search_path = public as $$ declare v_tpl text; v_garage record; k text; begin select modele into v_tpl from reminder_templates where garage_id = p_garage and type = p_type and actif; if v_tpl is null then v_tpl := public.default_reminder_template(p_type); end if; select nom, telephone into v_garage from garages where id = p_garage; v_tpl := replace(v_tpl, '{garage}', coalesce(v_garage.nom, '')); v_tpl := replace(v_tpl, '{tel_garage}', coalesce(v_garage.telephone, '')); for k in select jsonb_object_keys(p_ctx) loop v_tpl := replace(v_tpl, '{' || k || '}', coalesce(p_ctx ->> k, '')); end loop; return v_tpl; end $$;
create or replace function public.create_reminder(p_customer uuid, p_type text, p_canal text default 'sms', p_message text default null, p_scheduled_at timestamptz default null) returns uuid language plpgsql security definer set search_path = public as $$ declare v_c record; v_msg text; v_id uuid; begin if not public.has_role(array['proprietaire','gerant','reception']::public.user_role[]) then raise exception 'Rôle insuffisant'; end if; select * into v_c from customers where id = p_customer and garage_id = public.current_garage_id(); if not found then raise exception 'Client introuvable'; end if; v_msg := coalesce(nullif(trim(p_message), ''), public.build_reminder_message(public.current_garage_id(), p_type::public.reminder_type, jsonb_build_object('client', v_c.nom))); insert into reminders (garage_id, type, canal, customer_id, telephone, message, scheduled_at) values (public.current_garage_id(), p_type::public.reminder_type, p_canal::public.reminder_canal, p_customer, v_c.telephone, v_msg, coalesce(p_scheduled_at, now())) returning id into v_id; return v_id; end $$;
create or replace function public.generate_reminders(p_date date default current_date) returns int language plpgsql security definer set search_path = public as $$ declare v_count int := 0; v_garage uuid; v_garages uuid[]; r record; v_msg text; begin if auth.uid() is not null then v_garages := array[public.current_garage_id()]; else select array_agg(id) into v_garages from garages; end if; if v_garages is null then return 0; end if; foreach v_garage in array v_garages loop for r in select a.id appt_id, a.customer_id, c.nom client_nom, c.telephone from appointments a join customers c on c.id = a.customer_id where a.garage_id = v_garage and a.statut in ('attente','confirme') and date(a.starts_at) = p_date + 1 and coalesce(c.telephone, '') <> '' and not exists (select 1 from reminders x where x.appointment_id = a.id and x.type = 'rdv_j1' and x.statut <> 'annule') loop v_msg := public.build_reminder_message(v_garage, 'rdv_j1', jsonb_build_object('client', r.client_nom, 'heure', to_char(r.starts_at, 'HH24:MI'))); insert into reminders (garage_id, type, customer_id, appointment_id, telephone, message, scheduled_at) values (v_garage, 'rdv_j1', r.customer_id, r.appt_id, r.telephone, v_msg, (p_date || ' 08:00')::timestamp); v_count := v_count + 1; end loop; end loop; return v_count; end $$;
create or replace function public.send_reminder(p_reminder uuid) returns void language plpgsql security definer set search_path = public as $$ declare v_r record; v_webhook text; begin if not public.has_role(array['proprietaire','gerant','reception']::public.user_role[]) then raise exception 'Rôle insuffisant'; end if; select * into v_r from reminders where id = p_reminder and garage_id = public.current_garage_id() for update; if not found then raise exception 'Rappel introuvable'; end if; if v_r.statut <> 'programme' then raise exception 'Déjà traité'; end if; v_webhook := current_setting('app.reminder_webhook', true); if v_webhook is not null then perform net.http_post(url := v_webhook, headers := jsonb_build_object('Content-Type', 'application/json'), body := jsonb_build_object('reminder_id', p_reminder, 'canal', v_r.canal::text, 'to', v_r.telephone, 'message', v_r.message)); end if; update reminders set statut = 'envoye', sent_at = now(), provider = 'edge:dispatch' where id = p_reminder; perform public.audit_write(v_r.garage_id, 'Rappel envoyé', v_r.type::text); end $$;
create or replace function public.reminder_dispatch_done(p_reminder uuid, p_ok boolean, p_ref text default null, p_erreur text default null) returns void language plpgsql security definer set search_path = public as $$ begin update reminders set statut = case when p_ok then 'envoye'::public.reminder_statut else 'echec'::public.reminder_statut end, sent_at = now(), provider_ref = p_ref, erreur = p_erreur where id = p_reminder; end $$;
create or replace function public.cancel_reminder(p_reminder uuid) returns void language plpgsql security definer set search_path = public as $$ begin update reminders set statut = 'annule' where id = p_reminder and garage_id = public.current_garage_id() and statut = 'programme'; end $$;
